    File folder;String profile;final AtomicBoolean cancel=new AtomicBoolean();
    final ProviderHttp.Resolver publicDns=host->new InetAddress[]{InetAddress.getByAddress(new byte[]{93,(byte)184,(byte)216,34})};
    @Before public void before(){Context context=InstrumentationRegistry.getInstrumentation().getTargetContext();profile=UUID.randomUUID().toString().replace("-","");folder=new File(context.getCacheDir(),"provider-fixture-"+profile);folder.mkdirs();cancel.set(false);}
    @After public void after()throws Exception{delete(folder);KeyStore store=KeyStore.getInstance("AndroidKeyStore");store.load(null);store.deleteEntry("swir.providers.v1."+profile);}
    private static void delete(File file){if(file==null)return;if(file.isDirectory()){File[] children=file.listFiles();if(children!=null)for(File child:children)delete(child);}file.delete();}
    private ProviderRepository repo(ProviderHttp.Fetcher fetcher){return new ProviderRepository(folder,profile,fetcher,publicDns);}
    private ProviderHttp.Document doc(String url,String body){return new ProviderHttp.Document(url,body.getBytes(StandardCharsets.UTF_8),System.currentTimeMillis(),0);}
    private File vault(String id){return new File(new File(folder,profile),id+".vault");}
    private byte[] bytes(File file)throws Exception{try(FileInputStream input=new FileInputStream(file);ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] buffer=new byte[8192];int n;while((n=input.read(buffer))!=-1)out.write(buffer,0,n);return out.toByteArray();}}
    private void noPlainSecrets(File file,String... secrets)throws Exception{if(file.isDirectory()){File[] files=file.listFiles();if(files!=null)for(File child:files)noPlainSecrets(child,secrets);return;}String text=new String(bytes(file),StandardCharsets.ISO_8859_1);for(String secret:secrets)assertFalse("No plaintext secret in "+file.getName(),text.contains(secret));}
    private interface Throwing {void run()throws Exception;}
    private void rejects(Throwing operation)throws Exception{try{operation.run();fail("Expected a safe rejection");}catch(IOException expected){assertFalse(expected.toString().contains("fixture-secret"));}}
    private static String playlist(){return "#EXTM3U\n#EXTINF:-1 tvg-id=\"Yellow.pl\" group-title=\"Moje TV\",Żółw HD\n#EXTVLCOPT:http-user-agent=Fixture player\n#EXTVLCOPT:http-referrer=https://fixture.example:8443/view?token=fixture-secret\nlive/alpha.m3u8?token=fixture-secret|Authorization=Bearer%20fixture-secret\n#EXTINF:-1,Drugi Kanał\nhttps://media.example/live/beta.m3u8\n";}
    @Test public void urlPlaylistCustomPortRelativeStreamsVaultAndRestart()throws Exception{
        String url="https://fixture.example:8443/get.php?username=tester&password=fixture-secret";ProviderHttp.Fetcher fetcher=(u,h,c)->doc(u,playlist());ProviderRepository repository=repo(fetcher);ProviderRepository.SourceInfo info=repository.addM3u("Domowa telewizja",url,"",cancel);assertEquals(2,info.count);
        List<Station> saved=repo(fetcher).stations();assertEquals(2,saved.size());for(Station reference:saved){assertTrue(reference.url.startsWith("swir://provider/"+profile+"/"));assertTrue(LocalChannelSearch.prepare(reference.name).matches(reference));assertFalse(reference.toJson().toString().contains("fixture-secret"));assertEquals("",reference.userAgent);assertEquals("",reference.referrer);}
        Station resolved=repo(fetcher).resolve(saved.get(0),cancel);assertEquals("https://fixture.example:8443/live/alpha.m3u8?token=fixture-secret",resolved.url);assertEquals("Bearer fixture-secret",resolved.requestHeaders.get("Authorization"));assertEquals("https://fixture.example:8443/view?token=fixture-secret",resolved.requestHeaders.get("Referer"));assertEquals("Fixture player",resolved.requestHeaders.get("User-Agent"));assertFalse(resolved.toJson().toString().contains("fixture-secret"));assertEquals("",M3u.export(saved).replace("#EXTM3U\n",""));noPlainSecrets(folder,"fixture-secret","#EXTM3U","Domowa telewizja",url);
    }
