    @Test public void largeVaultRoundTripsBeyondLegacyChunkLimitsAndRejectsCorruption()throws Exception{
        ProviderVault storage=new ProviderVault(new File(folder,profile),profile);
        for(int length:new int[]{262177,1048589}){
            char[] characters=new char[length];for(int i=0;i<characters.length;i++)characters[i]=(char)('!'+(i*31+i/1024)%90);String payload=new String(characters);JSONObject value=new JSONObject().put("payload",payload).put("marker","large-fixture-secret");int plainBytes=value.toString().getBytes(StandardCharsets.UTF_8).length;assertTrue(plainBytes>262144);
            String id=UUID.randomUUID().toString().replace("-","");storage.write(id,value);File file=storage.file(id);assertEquals("Every ciphertext byte plus 16-byte tag and 18-byte header must be retained",plainBytes+34L,file.length());JSONObject reopened=storage.read(id);assertEquals(payload,reopened.getString("payload"));assertEquals("large-fixture-secret",reopened.getString("marker"));noPlainSecrets(file,"large-fixture-secret");
            byte[] changed=bytes(file);changed[changed.length/2]^=0x40;try(FileOutputStream output=new FileOutputStream(file)){output.write(changed);}rejects(()->storage.read(id));assertArrayEquals("Authentication failure does not rewrite the source",changed,bytes(file));storage.remove(id);
        }
    }
