        java.util.concurrent.atomic.AtomicReference<String> body=new java.util.concurrent.atomic.AtomicReference<>("#EXTM3U\n#EXTINF:-1,News\nhttps://cdn.example/alpha.m3u8?token=old\n#EXTINF:-1,News\nhttps://cdn.example/beta.m3u8?token=old\n");ProviderRepository repository=repo((u,h,c)->doc(u,body.get()));String id=repository.addM3u("Dwa News","https://fixture.example/list.m3u","",cancel).id;
        // Recreate the real pre-0.3.2 ordinal IDs, then refresh through production migration.
        ProviderVault storage=new ProviderVault(new File(folder,profile),profile);JSONObject saved=storage.read(id);org.json.JSONArray entries=saved.getJSONArray("entries");entries.getJSONObject(0).put("id",Station.sha256("||News|0"));entries.getJSONObject(1).put("id",Station.sha256("||News|1"));storage.write(id,saved);List<Station> old=repository.stations();Station alpha=old.get(0),beta=old.get(1);
        body.set("#EXTM3U\n#EXTINF:-1,News\nhttps://cdn.example/beta.m3u8?token=changed\n#EXTINF:-1,News\nhttps://cdn.example/alpha.m3u8?token=changed\n");repository.refresh(id,cancel);assertEquals("https://cdn.example/alpha.m3u8?token=changed",repository.resolve(alpha,cancel).url);assertEquals("https://cdn.example/beta.m3u8?token=changed",repository.resolve(beta,cancel).url);assertEquals(beta.providerChannelId,repository.stations().get(0).providerChannelId);
        body.set("#EXTM3U\n#EXTINF:-1,News\nhttps://cdn.example/changed-a.m3u8\n#EXTINF:-1,News\nhttps://cdn.example/changed-b.m3u8\n");repository.refresh(id,cancel);rejects(()->repository.resolve(alpha,cancel));rejects(()->repository.resolve(beta,cancel));assertEquals(2,repository.stations().size());
        body.set("#EXTM3U\n#EXTINF:-1,News\nhttps://cdn.example/same.m3u8?channel=a\n#EXTINF:-1,News\nhttps://cdn.example/same.m3u8?channel=b\n");String queryId=repository.addM3u("Query channels","https://fixture.example/query.m3u","",cancel).id;List<Station> queryRefs=new ArrayList<>();for(Station station:repository.stations())if(station.providerId.equals(queryId))queryRefs.add(station);Station channelA=queryRefs.get(0),channelB=queryRefs.get(1);for(int cycle=0;cycle<2;cycle++){body.set("#EXTM3U\n#EXTINF:-1,News\nhttps://cdn.example/same.m3u8?channel=b\n#EXTINF:-1,News\nhttps://cdn.example/same.m3u8?channel=a\n");repository.refresh(queryId,cancel);assertTrue(repository.resolve(channelA,cancel).url.endsWith("channel=a"));assertTrue(repository.resolve(channelB,cancel).url.endsWith("channel=b"));}
